"use client";

import { cva, type VariantProps } from "class-variance-authority";
import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";

/** Allowed progress size values. */
export type ProgressSize = NonNullable<VariantProps<typeof progressVariants>["size"]>;
/** Allowed progress variant values. */
export type ProgressVariant = NonNullable<VariantProps<typeof progressVariants>["variant"]>;

/** Props for progress. */
export interface ProgressProps
  extends Omit<
    ComponentProps<"div">,
    "role" | "aria-valuenow" | "aria-valuemin" | "aria-valuemax" | "aria-valuetext"
  > {
  /** Current progress value (0-100). Omit for indeterminate mode. */
  value?: number;
  /** Maximum value for the progress bar. */
  max?: number;
  /** Height of the progress bar track. */
  size?: ProgressSize;
  /**
   * "cells" (default) cuts track and fill into hard-edged character cells.
   * "bar" keeps the continuous rounded track for hairline-thin inline uses.
   */
  variant?: ProgressVariant;
  /** Custom text exposed through aria-valuetext for the current value. */
  valueText?: string;
}

/** Class variants for track. */
export const progressVariants = cva("relative w-full overflow-hidden bg-border", {
  variants: {
    size: {
      sm: "h-1",
      md: "h-2",
    },
    variant: {
      cells: "",
      bar: "rounded-sm",
    },
  },
  compoundVariants: [
    // A 4px track cannot carry an 8px cell, so size="sm" falls back to the
    // continuous bar — including its radius. See progress.css.
    { variant: "cells", size: "sm", class: "rounded-sm" },
  ],
  defaultVariants: {
    size: "md",
    variant: "cells",
  },
});

/** Root element with track and fill. Pass value for determinate, omit for indeterminate. */
export function Progress({
  value,
  max = 100,
  size = "md",
  variant = "cells",
  valueText,
  className,
  ...props
}: ProgressProps) {
  const normalizedMax = Number.isFinite(max) && max > 0 ? max : 100;
  const isIndeterminate = value === undefined;
  const rawValue = isIndeterminate ? 0 : value;
  const safeValue = Number.isNaN(rawValue) ? 0 : rawValue;
  const clampedValue = isIndeterminate
    ? undefined
    : Math.min(Math.max(0, safeValue), normalizedMax);
  const percentage = clampedValue === undefined ? undefined : (clampedValue / normalizedMax) * 100;

  return (
    <div
      {...props}
      role="progressbar"
      data-slot="progress"
      data-state={isIndeterminate ? "indeterminate" : "loaded"}
      data-size={size}
      data-variant={variant}
      aria-valuenow={clampedValue}
      aria-valuemin={0}
      aria-valuemax={normalizedMax}
      aria-valuetext={valueText}
      className={cn(progressVariants({ size, variant }), className)}
    >
      <div
        data-slot="progress-indicator"
        className={cn(
          "h-full bg-foreground motion-safe:transition-[width] motion-safe:duration-150",
          isIndeterminate && "progress-indeterminate",
        )}
        style={isIndeterminate ? undefined : { width: `${percentage}%` }}
      />
    </div>
  );
}

/*
 * Progress cell grid. The library already has one quantity language —
 * BlockBar's character cells — and a rounded material bar was a second one.
 * variant="cells" (the default) subdivides track and fill with a mask on the
 * ROOT, so both are cut by the same grid and the cells stay phase-aligned as
 * the fill grows. No per-cell DOM, no glyphs, no ARIA change.
 *
 * Radius lives in the CVA (bar keeps rounded-sm, cells does not), so it is not
 * re-declared here: a Tailwind utility would outrank this layer anyway.
 */
@layer components {
  [data-slot="progress"][data-variant="cells"] {
    --progress-cell: 8px;
    --progress-gap: 1px;
  }

  /* size="sm" is a 4px track — below the threshold where an 8px cell reads as
     anything but mush, so it degrades honestly to the continuous bar. */
  [data-slot="progress"][data-variant="cells"]:not([data-size="sm"]) {
    -webkit-mask-image: repeating-linear-gradient(
      90deg,
      #000 0 calc(var(--progress-cell) - var(--progress-gap)),
      transparent calc(var(--progress-cell) - var(--progress-gap)) var(--progress-cell)
    );
    mask-image: repeating-linear-gradient(
      90deg,
      #000 0 calc(var(--progress-cell) - var(--progress-gap)),
      transparent calc(var(--progress-cell) - var(--progress-gap)) var(--progress-cell)
    );
  }
}

@media (forced-colors: active) {
  /* Forced colors drops mask support unevenly and flattens the track/fill pair
     to the same system color, so fall back to an outlined track with a
     Highlight fill. */
  [data-slot="progress"] {
    -webkit-mask-image: none;
    mask-image: none;
    border: 1px solid CanvasText;
  }

  [data-slot="progress-indicator"] {
    background: Highlight;
  }
}
